/* From Uiverse.io by vinodjangid07  - Tags: button, hover effect, filter, setting */
.__UIV_SCOPE__ .filter {
  width: 50px;
  height: 50px;
  border-radius: 10px;
  display: flex;
  align-items: center;
  justify-content: center;
  border: 1px solid rgba(0, 0, 0, 0.192);
  cursor: pointer;
  box-shadow: 0px 10px 10px rgba(0, 0, 0, 0.021);
  transition: all 0.3s;
}

.__UIV_SCOPE__ .filter svg {
  height: 16px;
  fill: rgb(77, 77, 77);
  transition: all 0.3s;
}
.__UIV_SCOPE__ .filter:hover {
  box-shadow: 0px 10px 10px rgba(0, 0, 0, 0.11);
  background-color: rgb(59, 59, 59);
}
.__UIV_SCOPE__ .filter:hover svg {
  fill: white;
}
